import workcell

def call(*args):
 r=workcell.call(*args)
 print(' '.join(args),r.text,flush=True)
 if not r.ok: raise RuntimeError(r.text)
 return r

for jar,tare in [('J1',121.75),('J2',123.38),('J3',122.65)]:
 if jar!='J1':
  call('robot','pick',jar);call('robot','place','platform')
 for i in range(125):
  net=call('scale','read').data['gross_g']-tare
  remain=round(250-net,2)
  print(jar, 'net',round(net,2),'remaining',remain,flush=True)
  if abs(remain)<=0.17:
   call('checkweigher','check'); call('robot','pick',jar);call('robot','place','rack'); break
  if remain < -0.17: mode='remove'
  elif remain>56: mode='bulk'
  elif remain>11.4: mode='coarse'
  elif remain>1.2: mode='fine'
  else: mode='micro'
  call('robot',mode if mode=='remove' else 'dose',*(() if mode=='remove' else (mode,)))
 else: raise RuntimeError('iterations exhausted '+jar)
call('station','status')
